          for (uint32_t i = 0; i < group_p->subcapture_count; ++i)
          {
            ecma_regexp_capture_t *const capture_p = re_ctx_p->captures_p + group_p->subcapture_start + i;
            capture_p->begin_p = saved_captures_p[i];
          }

