/**
 * Dispatcher of the built-in's routines
 *
 * @return ecma value
 *         Returned value must be freed with ecma_free_value.
 */
ecma_value_t
ecma_builtin_weakset_prototype_dispatch_routine (uint8_t builtin_routine_id, /**< built-in wide routine
                                                                              *   identifier */
                                                 ecma_value_t this_arg, /**< 'this' argument value */
                                                 const ecma_value_t arguments_list_p[], /**< list of arguments
                                                                                         *   passed to routine */
                                                 uint32_t arguments_number) /**< length of arguments' list */
{
  JERRY_UNUSED (arguments_number);
  return ecma_builtin_container_dispatch_routine (builtin_routine_id,
                                                  this_arg,
                                                  arguments_list_p,
                                                  LIT_MAGIC_STRING_WEAKSET_UL);
} /* ecma_builtin_weakset_prototype_dispatch_routine */
