/** \addtogroup ecma ECMA
 * @{
 *
 * \addtogroup ecmabuiltins
 * @{
 *
 * \addtogroup %setiteratorprototype% ECMA %SetIteratorPrototype% object built-in
 * @{
 */

/**
 * The %SetIteratorPrototype% object's 'next' routine
 *
 * See also:
 *          ECMA-262 v6, 23.2.5.2.1
 *
 * Note:
 *     Returned value must be freed with ecma_free_value.
 *
 * @return iterator result object, if success
 *         error - otherwise
 */
static ecma_value_t
ecma_builtin_set_iterator_prototype_object_next (ecma_value_t this_val) /**< this argument */
{
  return ecma_op_container_iterator_next (this_val, ECMA_OBJECT_CLASS_SET_ITERATOR);
} /* ecma_builtin_set_iterator_prototype_object_next */

/**
 * Dispatcher of the built-in's routines
 *
 * @return ecma value
 *         Returned value must be freed with ecma_free_value.
 */
ecma_value_t
ecma_builtin_set_iterator_prototype_dispatch_routine (uint8_t builtin_routine_id, /**< built-in wide
                                                                                   *routine identifier */
                                                      ecma_value_t this_arg, /**< 'this' argument value */
                                                      const ecma_value_t arguments_list[], /**< list of arguments
                                                                                            *   passed to routine */
                                                      uint32_t arguments_number) /**< length of arguments' list */
{
  JERRY_UNUSED_2 (arguments_list, arguments_number);

  switch (builtin_routine_id)
  {
    case ECMA_BUILTIN_SET_ITERATOR_PROTOTYPE_OBJECT_NEXT:
    {
      return ecma_builtin_set_iterator_prototype_object_next (this_arg);
    }
    default:
    {
      JERRY_UNREACHABLE ();
    }
  }
} /* ecma_builtin_set_iterator_prototype_dispatch_routine */

/**
 * @}
 * @}
 * @}
 */

